```c
#include <stdio.h>

static char adj[1001][1001];

int main(void) {
    int S, T;
    if (scanf("%d %d", &S, &T) != 2) return 0;

    for (int i = 0; i < T; i++) {
        int X, Y;
        scanf("%d %d", &X, &Y);
        adj[X][Y] = 1;
        adj[Y][X] = 1;
    }

    int P;
    scanf("%d", &P);

    int answer = 0;

    for (int q = 0; q < P; q++) {
        int N;
        scanf("%d", &N);

        int prev;
        scanf("%d", &prev);

        int possible = 1;

        for (int i = 1; i < N; i++) {
            int cur;
            scanf("%d", &cur);

            if (!adj[prev][cur]) {
                possible = 0;
            }

            prev = cur;
        }

        if (possible) {
            answer++;
        }
    }

    printf("%d\n", answer);
    return 0;
}
```

